import { PrismaPg } from "@prisma/adapter-pg";
import { Prisma, PrismaClient } from "../generated/prisma/client";
import {
  prismaModelSignature,
  shouldReusePrismaClient,
} from "@/lib/prisma-signature";

/**
 * Signature of the generated data model this module was loaded with. It
 * changes whenever `prisma generate` adds or removes a model, which lets the
 * dev-only cache below discard a client generated by an older schema instead
 * of failing with "Unknown argument" / "undefined delegate" at query time.
 */
const signature = prismaModelSignature(Object.keys(Prisma.ModelName));

const globalForPrisma = globalThis as unknown as {
  prisma: PrismaClient | undefined;
  prismaSignature: string | undefined;
};

const cachedPrisma =
  globalForPrisma.prisma &&
  shouldReusePrismaClient(globalForPrisma.prismaSignature, signature)
    ? globalForPrisma.prisma
    : undefined;

export const prisma =
  cachedPrisma ??
  new PrismaClient({
    adapter: new PrismaPg({ connectionString: process.env.DATABASE_URL! }),
    log: process.env.NODE_ENV === "development" ? ["query", "error", "warn"] : ["error"],
  });

if (process.env.NODE_ENV !== "production") {
  globalForPrisma.prisma = prisma;
  globalForPrisma.prismaSignature = signature;
}
